// Simulate all five fundamental gates
const AND  = (a, b) => a & b;
const OR   = (a, b) => a | b;
const NOT  = (a)    => a ^ 1;          // XOR with 1 flips a single bit
const XOR  = (a, b) => a ^ b;
const NAND = (a, b) => NOT(AND(a, b));

// Half-adder: 1-bit addition with carry
function halfAdder(a, b) {
  return { sum: XOR(a, b), carry: AND(a, b) };
}

console.log(halfAdder(1, 0)); // { sum: 1, carry: 0 }
console.log(halfAdder(1, 1)); // { sum: 0, carry: 1 }  <- 1+1=10 in binary

// JS bitwise operators ARE logic gates on all bits simultaneously
console.log(0b1010 & 0b1100); // AND -> 8  (1000)
console.log(0b1010 | 0b1100); // OR  -> 14 (1110)
console.log(0b1010 ^ 0b1100); // XOR -> 6  (0110)

function NOT(x) { return x ^ 1; }
function AND(x, y) { return x & y; }

// De Morgan's laws verified at runtime
const a = 1, b = 0;
console.log(NOT(AND(a, b)) === (NOT(a) | NOT(b))); // true: NOT(A AND B) = NOT(A) OR NOT(B)
console.log(NOT(a | b)     === (NOT(a) & NOT(b))); // true: NOT(A OR B)  = NOT(A) AND NOT(B)

// NAND is universal: build OR using only NAND
const NAND2 = (x, y) => NOT(AND(x, y));
const OR_from_NAND = (x, y) => NAND2(NAND2(x, x), NAND2(y, y));
console.log(OR_from_NAND(1, 0)); // 1
console.log(OR_from_NAND(0, 0)); // 0
